for subject in somePath; do subname=$(basename "$subject"); echo "Processing $subname..."; mpr_dir=$(ls -d "$subject"MPR____*Scaled_2 2>/dev/null | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR__*Scaled_2 2>/dev/null | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR-R____*Scaled_2 2>/dev/null | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR-R__*Scaled_2 2>/dev/null | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR____*Scaled 2>/dev/null | grep -v "Scaled_2" | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR__*Scaled 2>/dev/null | grep -v "Scaled_2" | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR-R____*Scaled 2>/dev/null | grep -v "Scaled_2" | head -n1); [ -z "$mpr_dir" ] && mpr_dir=$(ls -d "$subject"MPR-R__*Scaled 2>/dev/null | grep -v "Scaled_2" | head -n1); if [ -n "$mpr_dir" ]; then mprname=$(basename "$mpr_dir"); date_dir=$(ls -d "$mpr_dir"/20* 2>/dev/null | sort | head -n1); if [ -n "$date_dir" ]; then datename=$(basename "$date_dir"); i_dir=$(ls -d "$date_dir"/I* 2>/dev/null | head -n1); if [ -n "$i_dir" ]; then nii_file=$(ls "$i_dir"/*.nii 2>/dev/null | head -n1); if [ -n "$nii_file" ]; then dest_dir="14_ADNI_prepared/EXLUDED_AD/${subname}_${mprname}_${datename}/anat"; mkdir -p "$dest_dir"; cp "$nii_file" "$dest_dir/" && echo "  Completed $subname" || echo "  -->Failed to copy $subname"; else echo "  -->No .nii file found for $subname"; fi; else echo "  -->No I* folder found for $subname"; fi; else echo "  -->No date folder found for $subname"; fi; else echo "  -->No MPR folder found for $subname"; fi; done
